CREATE TYPE "PurchaseOrderStatus" AS ENUM ('DRAFT', 'SUBMITTED', 'APPROVED', 'CANCELLED');
CREATE TABLE "PurchaseOrder" ("id" TEXT NOT NULL, "organizationId" TEXT NOT NULL, "projectId" TEXT NOT NULL, "supplierId" TEXT NOT NULL, "operationKey" VARCHAR(190) NOT NULL, "number" VARCHAR(64) NOT NULL, "currency" CHAR(3) NOT NULL, "status" "PurchaseOrderStatus" NOT NULL DEFAULT 'DRAFT', "total" DECIMAL(14,2) NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PurchaseOrder_pkey" PRIMARY KEY ("id"), CONSTRAINT "PurchaseOrder_org_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "PurchaseOrder_project_fkey" FOREIGN KEY ("projectId") REFERENCES "Project"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "PurchaseOrder_supplier_fkey" FOREIGN KEY ("organizationId", "supplierId") REFERENCES "Supplier"("organizationId", "id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE "PurchaseOrderLine" ("id" TEXT NOT NULL, "purchaseOrderId" TEXT NOT NULL, "description" VARCHAR(220) NOT NULL, "unit" VARCHAR(32) NOT NULL, "quantity" DECIMAL(14,3) NOT NULL, "unitPrice" DECIMAL(14,2) NOT NULL, "costCode" VARCHAR(96), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PurchaseOrderLine_pkey" PRIMARY KEY ("id"), CONSTRAINT "PurchaseOrderLine_order_fkey" FOREIGN KEY ("purchaseOrderId") REFERENCES "PurchaseOrder"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "PurchaseOrderLine_quantity_check" CHECK ("quantity" > 0), CONSTRAINT "PurchaseOrderLine_price_check" CHECK ("unitPrice" >= 0));
CREATE UNIQUE INDEX "PurchaseOrder_projectId_id_key" ON "PurchaseOrder"("projectId", "id");
CREATE UNIQUE INDEX "PurchaseOrder_projectId_operationKey_key" ON "PurchaseOrder"("projectId", "operationKey");
CREATE UNIQUE INDEX "PurchaseOrder_projectId_number_key" ON "PurchaseOrder"("projectId", "number");
CREATE INDEX "PurchaseOrder_projectId_status_createdAt_idx" ON "PurchaseOrder"("projectId", "status", "createdAt");
CREATE INDEX "PurchaseOrderLine_purchaseOrderId_idx" ON "PurchaseOrderLine"("purchaseOrderId");
